#include <filesystem>
waymo::open_dataset::Scenario load(const std::string&p){std::ifstream f(p,std::ios::binary);auto n=std::filesystem::file_size(p);if(!n||n>64*1024*1024)throw std::runtime_error("native payload cap");auto b=read(f,n);waymo::open_dataset::Scenario s;if(!s.ParseFromString(b))throw std::runtime_error("native protobuf");known(s);return s;}
void save(const waymo::open_dataset::Scenario&s,const std::string&p){if(std::filesystem::exists(p))throw std::runtime_error("output exists");std::ofstream f(p,std::ios::binary);if(!s.SerializeToOstream(&f))throw std::runtime_error("write");}
int main(int argc,char**argv){try{if(argc<5)throw std::runtime_error("args");std::string mode=argv[1];if(mode=="join"){if(argc!=6)throw std::runtime_error("authenticated external scenario key required");}if(mode=="join"){auto base=load(argv[2]);std::ifstream f(argv[3],std::ios::binary);auto l=read(f,8);if(le(read(f,4))!=mask(crc(l)))throw std::runtime_error("length CRC");auto n=le(l);if(!n||n>64*1024*1024)throw std::runtime_error("frame cap");auto b=read(f,n);if(le(read(f,4))!=mask(crc(b))||f.peek()!=EOF)throw std::runtime_error("CRC or duplicate records");waymo::open_dataset::Scenario ext;if(!ext.ParseFromString(b))throw std::runtime_error("extension protobuf");known(ext);std::cout<<"BASE_ID "<<base.scenario_id()<<" EXT_ID "<<ext.scenario_id()<<" BASE_SENSOR_COUNTS "<<base.compressed_frame_laser_data_size()<<" "<<base.frame_camera_tokens_size()<<"\n";if(base.scenario_id()!=argv[5]||(!ext.scenario_id().empty()&&base.scenario_id()!=ext.scenario_id())||base.compressed_frame_laser_data_size()||base.frame_camera_tokens_size())throw std::runtime_error("identity/duplicate augmentation");int count=base.current_time_index()+1;if(ext.compressed_frame_laser_data_size()!=count||ext.frame_camera_tokens_size()!=count)throw std::runtime_error("sensor timeline");std::vector<const google::protobuf::FieldDescriptor*> fields;ext.GetReflection()->ListFields(ext,&fields);for(auto x:fields){std::cout<<"EXT_FIELD "<<x->number()<<" "<<x->name()<<"\n";if(x->number()!=5&&x->number()!=12&&x->number()!=13)throw std::runtime_error("unexpected extension contract field");}uint32_t low=~0u,high=0;int tokens=0;for(const auto&frame:ext.frame_camera_tokens()){std::set<int> cameras;for(const auto&camera:frame.camera_tokens()){if(!camera.has_camera_name()||!cameras.insert(camera.camera_name()).second||camera.tokens_size()!=256)throw std::runtime_error("camera token support");for(auto t:camera.tokens()){low=std::min(low,t);high=std::max(high,t);tokens++;}}std::cout<<"CAMERAS "<<cameras.size()<<" IDS";for(auto id:cameras)std::cout<<" "<<id;std::cout<<"\n";if(cameras.empty())throw std::runtime_error("empty camera support");}for(auto&x:ext.compressed_frame_laser_data())*base.add_compressed_frame_laser_data()=x;for(auto&x:ext.frame_camera_tokens())*base.add_frame_camera_tokens()=x;save(base,argv[4]);std::cout<<"JOINED "<<base.scenario_id()<<" FRAMES "<<count<<" TOKENS "<<tokens<<" MIN "<<low<<" MAX "<<high<<"\n";}
else if(mode=="check"){auto truth=load(argv[2]),obs=load(argv[3]);int n=truth.current_time_index()+1;if(obs.scenario_id()!=truth.scenario_id()||obs.current_time_index()!=n-1||obs.timestamps_seconds_size()!=n||obs.dynamic_map_states_size()!=n||obs.tracks_size()!=truth.tracks_size()||obs.tracks_to_predict_size()!=0||obs.objects_of_interest_size()!=0||obs.compressed_frame_laser_data_size()!=n||obs.frame_camera_tokens_size()!=n||obs.sdc_track_index()!=truth.sdc_track_index()||obs.map_features_size()!=truth.map_features_size())throw std::runtime_error("causal identity/count");for(int i=0;i<n;i++){if(obs.timestamps_seconds(i)!=truth.timestamps_seconds(i)||obs.dynamic_map_states(i).SerializeAsString()!=truth.dynamic_map_states(i).SerializeAsString()||obs.compressed_frame_laser_data(i).SerializeAsString()!=truth.compressed_frame_laser_data(i).SerializeAsString()||obs.frame_camera_tokens(i).SerializeAsString()!=truth.frame_camera_tokens(i).SerializeAsString())throw std::runtime_error("native prefix mismatch");}for(int i=0;i<truth.tracks_size();i++){auto&a=truth.tracks(i);auto&b=obs.tracks(i);if(a.id()!=b.id()||a.object_type()!=b.object_type()||b.states_size()!=n)throw std::runtime_error("track causal mismatch");for(int j=0;j<n;j++)if(a.states(j).SerializeAsString()!=b.states(j).SerializeAsString())throw std::runtime_error("state prefix mismatch");}for(int i=0;i<truth.map_features_size();i++)if(truth.map_features(i).SerializeAsString()!=obs.map_features(i).SerializeAsString())throw std::runtime_error("map mismatch");*truth.add_compressed_frame_laser_data()=truth.compressed_frame_laser_data(n-1);save(truth,argv[4]);std::cout<<"CHECKED native causal prefix "<<n<<" frames\n";}
else throw std::runtime_error("mode");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
